pub const DRAIN_PER_CONNECTION: Duration = Duration::from_secs(3);
pub const KILL_GRACE: Duration = Duration::from_millis(250);
pub const MAX_CARRY_BYTES: usize = 128 * 1024 * 1024;
pub const MAX_CARRIED_FLOWS: usize = MAX_CARRY_BYTES / WORST_CASE_PER_FLOW;
pub const RESUME_BUDGET: Duration = Duration::from_secs(15);

pub const PIDFILE: &str = "tundra-node.pid";

const WORST_CASE_PER_FLOW: usize = 2 * crate::node::relay::tcp::RELAY_BUF;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Killed {
    Deadline,
    Budget,
    Anomaly,
    Unmatched,
    NoResume,
    ExecFailed,
}

impl Killed {
    #[inline]
    pub fn to_str(self) -> &'static str {
        match self {
            Self::Deadline => "deadline",
            Self::Budget => "budget",
            Self::Anomaly => "anomaly",
            Self::Unmatched => "unmatched",
            Self::NoResume => "no_resume",
            Self::ExecFailed => "exec_failed",
        }
    }

    #[inline]
    pub const fn variants() -> &'static [Self] {
        &[
            Self::Deadline,
            Self::Budget,
            Self::Anomaly,
            Self::Unmatched,
            Self::NoResume,
            Self::ExecFailed,
        ]
    }
}

#[derive(Debug, Default)]
pub struct Counters {
    triggers: AtomicU64,
    triggers_ignored: AtomicU64,

    exec_failed: AtomicU64,
    pub blob_unusable: AtomicU64,

    peers_drained: AtomicU64,
    peers_failed: AtomicU64,

    flows_frozen: AtomicU64,
    flows_carried: AtomicU64,
    pub flows_resumed: AtomicU64,
    pub resume_refused: AtomicU64,

    pub tokens_reused: AtomicU64,
    bytes_carried: AtomicU64,
    killed: [AtomicU64; Killed::variants().len()],
}

impl Counters {
    pub fn killed(&self, reason: Killed, n: u64) {
        if n == 0 {
            return;
        }

        for (r, counter) in Killed::variants().iter().zip(&self.killed) {
            if *r == reason {
                counter.fetch_add(n, Relaxed);
                return;
            }
        }
    }

    #[inline]
    pub fn killed_total(&self) -> u64 {
        self.killed.iter().map(|c| c.load(Relaxed)).sum()
    }

    pub fn killed_pairs(&self) -> Vec<(&'static str, u64)> {
        Killed::variants()
            .iter()
            .zip(&self.killed)
            .map(|(r, counter)| (r.to_str(), counter.load(Relaxed)))
            .collect()
    }

    fn killed_json(&self) -> Value {
        Value::Object(
            Killed::variants()
                .iter()
                .zip(&self.killed)
                .map(|(r, counter)| (r.to_str().into(), json!(counter.load(Relaxed))))
                .collect(),
        )
    }
}

#[derive(Debug, Clone)]
pub struct PeerOutcome {
    pub peer: uuid::Uuid,
    pub name: String,
    pub outcome: &'static str,
    pub flows: usize,
}

#[derive(Debug, Clone, Default)]
pub struct Report {
    pub unix: u64,
    pub pause_ms: u64,
    pub flows_survived: u64,
    pub flows_killed: u64,
    pub peers: Vec<PeerOutcome>,
}

#[derive(Debug)]
pub struct Handover {
    /// Regenerated by every exec, so a peer can tell a reconnection from a duplicate.
    pub instance_id: u64,
    pub generation: u64,

    binary: Option<PathBuf>,
    args: Vec<OsString>,

    drain_timeout: Duration,
    peer_resume_timeout: Duration,

    pub counters: Counters,
    in_flight: AtomicBool,
    /// No `Instant` survives the exec, and the pause this measures spans it.
    triggered_unix_ms: AtomicU64,
    pending: parking_lot::Mutex<Report>,
    last: parking_lot::Mutex<Option<Report>>,
}

impl Handover {
    #[inline]
    pub fn new(
        binary: Option<PathBuf>,
        args: Vec<OsString>,
        generation: u64,
        drain_timeout: Duration,
        peer_resume_timeout: Duration,
    ) -> Self {
        Self {
            instance_id: rand::random(),
            generation,
            binary,
            args,
            drain_timeout,
            peer_resume_timeout,
            counters: Counters::default(),
            in_flight: AtomicBool::new(false),
            triggered_unix_ms: AtomicU64::new(0),
            pending: parking_lot::Mutex::new(Report::default()),
            last: parking_lot::Mutex::new(None),
        }
    }

    pub fn begin(&self) -> bool {
        if self.in_flight.swap(true, Relaxed) {
            self.counters.triggers_ignored.fetch_add(1, Relaxed);
            tracing::warn!("a handover is already running, ignoring this trigger");
            return false;
        }

        self.counters.triggers.fetch_add(1, Relaxed);

        true
    }

    #[inline]
    pub fn finish(&self) {
        self.in_flight.store(false, Relaxed);
    }

    #[inline]
    pub fn mark_triggered(&self, unix_ms: u64) {
        self.triggered_unix_ms.store(unix_ms, Relaxed);
    }

    #[inline]
    pub fn pause_ms(&self) -> u64 {
        match self.triggered_unix_ms.load(Relaxed) {
            0 => 0,
            started => unix_millis().saturating_sub(started),
        }
    }

    #[inline]
    pub fn is_in_flight(&self) -> bool {
        self.in_flight.load(Relaxed)
    }

    pub fn record(&self, report: Report) {
        tracing::info!(
            pause_ms = report.pause_ms,
            survived = report.flows_survived,
            killed = report.flows_killed,
            "handover complete"
        );

        *self.last.lock() = Some(report);
    }

    pub fn with_pending<T>(&self, f: impl FnOnce(&mut Report) -> T) -> T {
        f(&mut self.pending.lock())
    }

    pub fn json(&self) -> Value {
        let counters = &self.counters;
        let last = self.last.lock().clone();

        json!({
            "instance_id": self.instance_id.to_string(),
            "generation": self.generation,
            "in_flight": self.is_in_flight(),
            "binary": self.binary.as_ref().map(|p| p.display().to_string()),
            "last": last.map(|r| json!({
                "unix": r.unix,
                "pause_ms": r.pause_ms,
                "flows_survived": r.flows_survived,
                "flows_killed": r.flows_killed,
                "peers": r.peers.iter().map(|p| json!({
                    "uuid": p.peer,
                    "name": p.name,
                    "outcome": p.outcome,
                    "flows": p.flows,
                })).collect::<Vec<_>>(),
            })),
            "counters": {
                "triggers": counters.triggers.load(Relaxed),
                "triggers_ignored": counters.triggers_ignored.load(Relaxed),
                "exec_failed": counters.exec_failed.load(Relaxed),
                "blob_unusable": counters.blob_unusable.load(Relaxed),
                "peers_drained": counters.peers_drained.load(Relaxed),
                "peers_failed": counters.peers_failed.load(Relaxed),
                "flows_frozen": counters.flows_frozen.load(Relaxed),
                "flows_carried": counters.flows_carried.load(Relaxed),
                "flows_resumed": counters.flows_resumed.load(Relaxed),
                "flows_killed": counters.killed_total(),
                "resume_refused": counters.resume_refused.load(Relaxed),
                "tokens_reused": counters.tokens_reused.load(Relaxed),
                "bytes_carried": counters.bytes_carried.load(Relaxed),
            },
            "killed_by_reason": counters.killed_json(),
        })
    }
}

pub fn release_expired(
    frozen: &frozen::FrozenStore,
    peers: &crate::node::quic::registry::PeerRegistry,
    gate: &gate::AcceptGate,
    now: std::time::Instant,
) -> usize {
    let (gave_up, killed) = frozen.reap(now);
    for peer in gave_up {
        peers.unsuppress_dial(&peer);
        gate.resume_peer(&peer);
    }

    killed
}

#[inline]
pub fn unix_millis() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_or(0, |d| d.as_millis() as u64)
}

#[inline]
pub fn pidfile_path(data_dir: &Path) -> PathBuf {
    data_dir.join(PIDFILE)
}

pub fn write_pidfile(data_dir: &Path) -> Result<(), anyhow::Error> {
    let path = pidfile_path(data_dir);
    std::fs::create_dir_all(data_dir)
        .context(format!("failed to create {}", data_dir.display()))?;

    std::fs::write(&path, format!("{}\n", std::process::id()))
        .context(format!("failed to write {}", path.display()))
}

pub fn signal_running(data_dir: &Path) -> Result<i32, anyhow::Error> {
    let path = pidfile_path(data_dir);
    let text =
        std::fs::read_to_string(&path).context(format!("failed to read {}", path.display()))?;
    let pid: i32 = text
        .trim()
        .parse()
        .context(format!("failed to parse a pid from {}", path.display()))?;

    // kill(0) signals our whole process group and kill(-1) everything we can reach
    if pid <= 1 {
        return Err(anyhow::anyhow!("{} names pid {pid}", path.display()));
    }

    nix::sys::signal::kill(
        nix::unistd::Pid::from_raw(pid),
        nix::sys::signal::Signal::SIGUSR2,
    )
    .context(format!("failed to signal pid {pid}"))?;

    Ok(pid)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::node::quic::registry::PeerRegistry;
    use std::time::Instant;
    use tundra_common::flow::Parity;

    fn handover() -> Handover {
        Handover::new(
            None,
            Vec::new(),
            0,
            Duration::from_secs(5),
            Duration::from_secs(30),
        )
    }

    // Handover

    #[test]
    fn begin_honours_only_one_trigger_at_a_time() {
        let h = handover();
        assert!(h.begin());
        assert!(!h.begin());
        assert!(!h.begin());
        assert_eq!(h.counters.triggers.load(Relaxed), 1);
        assert_eq!(h.counters.triggers_ignored.load(Relaxed), 2);

        h.finish();
        assert!(h.begin());
    }

    #[test]
    fn instance_id_differs_between_two_images_of_the_same_pid() {
        let ids: Vec<_> = (0..8).map(|_| handover().instance_id).collect();
        let unique: std::collections::HashSet<_> = ids.iter().collect();
        assert_eq!(unique.len(), ids.len());
    }

    // Killed

    #[test]
    fn killed_reasons_have_distinct_names_and_their_own_counters() {
        let names: Vec<_> = Killed::variants().iter().map(|r| r.to_str()).collect();
        let unique: std::collections::HashSet<_> = names.iter().collect();
        assert_eq!(names.len(), unique.len());

        let c = Counters::default();
        for (i, reason) in Killed::variants().iter().enumerate() {
            c.killed(*reason, i as u64 + 1);
        }
        assert_eq!(
            c.killed_total(),
            (1..=Killed::variants().len() as u64).sum::<u64>()
        );

        let json = c.killed_json();
        assert_eq!(json.as_object().unwrap().len(), Killed::variants().len());
        assert_eq!(json["deadline"], 1);
    }

    #[test]
    fn killed_records_each_variant_spelled_out_by_hand() {
        // looping over variants() here would never catch a reason missing from it
        let c = Counters::default();
        for reason in [
            Killed::Deadline,
            Killed::Budget,
            Killed::Anomaly,
            Killed::Unmatched,
            Killed::NoResume,
            Killed::ExecFailed,
        ] {
            c.killed(reason, 1);
        }
        assert_eq!(c.killed_total(), 6);
    }

    #[test]
    fn killed_with_a_zero_increment_leaves_the_counter_alone() {
        let c = Counters::default();
        c.killed(Killed::Deadline, 0);
        assert_eq!(c.killed_total(), 0);
    }

    // release_expired

    #[test]
    fn release_expired_lifts_the_dial_and_accept_blocks_it_put_on_a_peer() {
        let store = frozen::FrozenStore::default();
        let peers = PeerRegistry::new(uuid::Uuid::from_u128(1));
        let gate = gate::AcceptGate::default();

        let peer = uuid::Uuid::from_u128(2);
        let now = Instant::now();
        store.park(
            peer,
            Parity::Even,
            now + Duration::from_secs(30),
            Vec::new(),
        );
        peers.suppress_dial(peer);
        gate.pause_peer(peer);

        assert_eq!(release_expired(&store, &peers, &gate, now), 0);
        assert!(gate.paused(&peer));
        assert!(peers.dial_suppressed(&peer));

        release_expired(&store, &peers, &gate, now + Duration::from_secs(31));
        assert!(!gate.paused(&peer));
        assert!(!peers.dial_suppressed(&peer));
    }

    // MAX_CARRIED_FLOWS

    #[test]
    fn the_carried_flow_cap_exactly_spends_the_byte_budget() {
        assert_eq!(MAX_CARRIED_FLOWS * WORST_CASE_PER_FLOW, MAX_CARRY_BYTES);
        const {
            assert!(MAX_CARRIED_FLOWS >= 1024);
        }
        assert!(RESUME_BUDGET < crate::config::RestartConfig::default().peer_resume_timeout());
    }

    // write_pidfile

    #[test]
    fn write_pidfile_names_this_process_so_restart_needs_no_argument() {
        let dir = std::env::temp_dir().join(format!("tundra-pid-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        write_pidfile(&dir).unwrap();

        let text = std::fs::read_to_string(pidfile_path(&dir)).unwrap();
        assert_eq!(text.trim().parse::<u32>().unwrap(), std::process::id());
        std::fs::remove_dir_all(&dir).ok();
    }

    // signal_running

    #[test]
    fn signal_running_without_a_pidfile_fails_rather_than_guessing() {
        let dir = std::env::temp_dir().join("tundra-pid-missing");
        let _ = std::fs::remove_dir_all(&dir);
        assert!(signal_running(&dir).is_err());
    }
}
